// db.js: saves the app's data in database.db (SQLite). Students do NOT edit this file.
// Uses Node's built-in SQLite (Node 22.13 or newer). On older Node, data stays in memory only.
const path = require("path");
let DB = null;
const warn = process.emitWarning;
try {
  process.emitWarning = () => {}; // hide the "experimental" warning
  const { DatabaseSync } = require("node:sqlite");
  DB = new DatabaseSync(path.join(__dirname, "database.db"));
} catch (e) {
  console.log("  (Note: SQLite needs Node 22.13+. Your data is kept in memory only.)");
} finally {
  process.emitWarning = warn;
}

function run(sql, ...params) {
  if (DB) DB.prepare(sql).run(...params);
}
function rows(sql, ...params) {
  return DB ? DB.prepare(sql).all(...params) : [];
}
function many(ops) {
  if (!DB) return;
  DB.exec("BEGIN");
  try {
    for (const [sql, params] of ops) DB.prepare(sql).run(...params);
    DB.exec("COMMIT");
  } catch (e) {
    DB.exec("ROLLBACK");
    throw e;
  }
}

module.exports = { run, rows, many, enabled: !!DB };
